45	void Fisher::giveFinalReport(RecordOutputMgr *outputMgr)
46	{
47	    double left, right, two;
48	
49	    long long genomeSize = _context->getGenomeFile()->getGenomeSize();
50	    if(_haveExclude){
51	        genomeSize -= _excludeFile->getTotalFlattenedLength();
52	    }
53	    // bases covered by neither
54	    long long n22_full_bases = genomeSize;
55	    //long long n22_bases = genomeSize - _queryUnion - _dbUnion + _intersectionVal;
56	    long double dMean = 1.0 + _dbUnion / (long double)_dbCounts;
57	    long double qMean = 1.0 + _queryUnion / (long double)_queryCounts;
58	
59	    // heursitic, but seems to work quite well -- better than doing more intuitive sum then divide.
60	    long double bMean = (qMean + dMean);
61	    //bMean = (_unionVal + 2.0 * _intersectionVal) / (long double)(_dbCounts + _queryCounts);
62	
63	    long long n11 = (long)_overlapCounts;
64	    // this could be < 0 because multiple overlaps
65	    long long n12 = (long)max(0L, (long)_queryCounts - (long)_overlapCounts);
66	    long long n21 = max(0L, (long)(_dbCounts - _overlapCounts));
67	    long long n22_full = max(n21 + n12 + n11, (long long)(n22_full_bases / bMean));
68	    long long n22 = max(0L, (long)(n22_full - n12 - n21 - n11));
69	
70	    printf("# Number of query intervals: %lu\n", _queryCounts);
71	    printf("# Number of db intervals: %lu\n", _dbCounts);
72	    printf("# Number of overlaps: %lu\n", _overlapCounts);
73	    printf("# Number of possible intervals (estimated): %lld\n", n22_full);
74	
75	    printf("# phyper(%lld - 1, %lu, %lld - %lu, %lu, lower.tail=F)\n", n11, _queryCounts, n22_full, _queryCounts, _dbCounts);
76	    cout << "# Contingency Table Of Counts" << endl;
77	    printf("#_________________________________________\n");
78	    printf("#           | %-12s | %-12s |\n", " in -b", "not in -b");
79	    printf("#     in -a | %-12lld | %-12lld |\n", n11, n12);
80	    printf("# not in -a | %-12lld | %-12lld |\n", n21, n22);
81	    printf("#_________________________________________\n");
82	
83	    kt_fisher_exact(n11, n12, n21, n22, &left, &right, &two);
84	    double ratio = ((double)n11 / (double)n12) / ((double)n21 / (double)n22);
85	    
86	    printf("# p-values for fisher's exact test\n");
87	    printf("left\tright\ttwo-tail\tratio\n");
88	    
89	    /* Some implementations report NAN as negative, some as positive. To ensure
90	     * we get consistent output from each compiler, we should do our own test.
91	     * Since the test script assumes "-nan", let's setle on that.
92	     */
93	    if(std::isnan(ratio)) {
94	        printf("%.5g\t%.5g\t%.5g\t-nan\n", left, right, two);
95	    } else {
96	        printf("%.5g\t%.5g\t%.5g\t%.3f\n", left, right, two, ratio);
97	    }
98	}
