127	void NewChromSweep::scanCache(int dbIdx, RecordKeyVector &retList) {
128	    recListIterType cacheIter = _caches[dbIdx].begin();
129	    while (cacheIter != _caches[dbIdx].end())
130	    {
131	        Record *cacheRec = cacheIter->value();
132	        if (_currQueryRec->sameChrom(cacheRec) && !_currQueryRec->after(cacheRec)) 
133	        {
134	            if (intersects(_currQueryRec, cacheRec)) 
135	            {
136	                retList.push_back(cacheRec);
137	            } 
138	            else if (cacheRec->after(_currQueryRec)) break; // cacheRec is after the query rec, stop scanning.
139	            cacheIter = _caches[dbIdx].next();
140	        }
141	        else 
142	        {
143	            _dbFRMs[dbIdx]->deleteRecord(cacheRec);
144	            cacheIter = _caches[dbIdx].deleteCurrent();
145	        }
146	    }
147	}
148	
149	void NewChromSweep::clearCache(int dbIdx)
150	{
151	    //delete all objects pointed to by cache
152	    recListType &cache = _caches[dbIdx];
153	    for (recListIterType iter = cache.begin(); iter != cache.end(); iter = cache.next()) 
154	    {
155	        _dbFRMs[dbIdx]->deleteRecord(iter->value());
156	    }
157	    cache.clear();
158	}
159	
160	void NewChromSweep::masterScan(RecordKeyVector &retList) {
161	
162	    for (int i=0; i < _numDBs; i++) 
163	    {
164	        if (dbFinished(i) || chromChange(i, retList, true)) 
165	        {
166	            continue;
167	        } 
168	        else 
169	        {
170	
171	            // scan the database cache for hits
172	            scanCache(i, retList);
173	            //skip if we hit the end of the DB
174	            // advance the db until we are ahead of the query. update hits and cache as necessary
175	            while (_currDbRecs[i] != NULL &&
176	                    _currQueryRec->sameChrom(_currDbRecs[i]) &&
177	                    !(_currDbRecs[i]->after(_currQueryRec))) 
178	            {
179	                if (intersects(_currQueryRec, _currDbRecs[i])) {
180	                    retList.push_back(_currDbRecs[i]);
181	                }
182	                if (_currQueryRec->after(_currDbRecs[i])) {
183	                    _dbFRMs[i]->deleteRecord(_currDbRecs[i]);
184	                    _currDbRecs[i] = NULL;
185	                } else {
186	                    _caches[i].push_back(_currDbRecs[i]);
187	                    _currDbRecs[i] = NULL;
188	                }
189	                nextRecord(false, i);
190	            }
191	        }
192	    }
193	}
194	
195	bool NewChromSweep::chromChange(int dbIdx, RecordKeyVector &retList, bool wantScan)
196	{
197	    const Record *dbRec = _currDbRecs[dbIdx];
198	
199	    if (_currQueryRec != NULL && _currQueryChromName != _prevQueryChromName) {
200	        _context->testNameConventions(_currQueryRec);
201	        testChromOrder(_currQueryRec);
202	    }
203	
204	    if (dbRec != NULL) {
205	        _context->testNameConventions(dbRec);
206	        testChromOrder(dbRec);
207	    }
208	
209	    // If the query rec and db rec are on the same chrom, stop.
210	    if (dbRec != NULL && _currQueryRec != NULL && _currQueryRec->sameChrom(dbRec)) return false;
211	
212	
213	    if (dbRec == NULL || _currQueryRec == NULL) return false;
214	
215	    if (queryChromAfterDbRec(dbRec)) {
216	        // the query is ahead of the database. fast-forward the database to catch-up.
217	        string oldDbChrom(dbRec->getChrName());
218	        while (dbRec != NULL && queryChromAfterDbRec(dbRec)) 
219	        {
220	            _dbFRMs[dbIdx]->deleteRecord(dbRec);
221	            if (!nextRecord(false, dbIdx)) break;
222	            dbRec =  _currDbRecs[dbIdx];
223	            const string &newDbChrom = dbRec->getChrName();
224	            if (newDbChrom != oldDbChrom) {
225	                testChromOrder(dbRec);
226	                oldDbChrom = newDbChrom;
227	            }
228	        }
229	        clearCache(dbIdx);
230	        return false;
231	    } else {
232	        // the database is ahead of the query.
233	        // scan the cache for remaining hits on the query's current chrom.
234	        if (wantScan) scanCache(dbIdx, retList);
235	        return true;
236	    }
237	}
238	
239	
240	bool NewChromSweep::next(RecordKeyVector &retList) {
241	    retList.clearVector();
242	
243	    //make sure the first read of the query file is tested for chrom sort order.
244	    bool needTestSortOrder = false;
245	    if (_currQueryRec != NULL) {
246	        _queryFRM->deleteRecord(_currQueryRec);
247	    } else {
248	        needTestSortOrder = true;
249	    }
250	
251	    if (!nextRecord(true)) { // query EOF hit
252	        return false; 
253	    }
254	
255	    retList.setKey(_currQueryRec);
256	
257	    if (needTestSortOrder) testChromOrder(_currQueryRec);
258	
259	    if (allCurrDBrecsNull() && allCachesEmpty() && !_runToQueryEnd) {
260	        _testLastQueryRec = true;
261	        return false;
262	    }
263	    _currQueryChromName = _currQueryRec->getChrName();
264	
265	    masterScan(retList);
266	
267	    if (_context->getSortOutput()) {
268	        retList.sortVector();
269	    }
270	
271	    _prevQueryChromName = _currQueryChromName;
272	    return true;
273	}
274	
275	bool NewChromSweep::nextRecord(bool query, int dbIdx) {
276	    if (query) {
277	        _currQueryRec = _queryFRM->getNextRecord();
278	        if (_currQueryRec != NULL) {
279	            _queryRecordsTotalLength += (unsigned long)(_currQueryRec->getLength(_context->getObeySplits()));
280	            _queryTotalRecords++;
281	            return true;
282	        }
283	        return false;
284	    } else { //database
285	        Record *rec = _dbFRMs[dbIdx]->getNextRecord();
286	        _currDbRecs[dbIdx] = rec;
287	        if (rec != NULL) {
288	            _databaseRecordsTotalLength += (unsigned long)(rec->getLength(_context->getObeySplits()));
289	            _databaseTotalRecords++;
290	            return true;
291	        }
292	        return false;
293	    }
294	}
