335	
336	void NewChromSweep::testChromOrder(const Record *rec)
337	{
338	    // Only use this method if we don't have a genome file
339	    // and the record is valid
340	    if (_context->hasGenomeFile() || rec == NULL) return;
341	
342	    int fileIdx = rec->getFileIdx();
343	
344	    const string &chrom = rec->getChrName();
345	
346	    findChromOrder(rec);
347	
348	    //determine what the previous chrom was for this file.
349	
350		if (_filePrevChrom[fileIdx] == NULL) {
351			_filePrevChrom[fileIdx] = strdup(chrom.c_str());
352			return;
353		}
354	
355		if (strcmp(_filePrevChrom[fileIdx], chrom.c_str()) == 0) return;
356	
357		const string prevChrom(_filePrevChrom[fileIdx]);
358	
359		free(_filePrevChrom[fileIdx]);
360		_filePrevChrom[fileIdx] = strdup(chrom.c_str());
361	
362	
363	    if (verifyChromOrderMismatch(chrom, prevChrom, fileIdx)) {
364	        fprintf(stderr, "ERROR: chromomsome sort ordering for file %s is inconsistent with other files. Record was:\n", _context->getInputFileName(fileIdx).c_str());
365	        rec->print(stderr, true);
366	        exit(1);
367	    }
368	
369	    if (!_lexicoDisproven && chrom < prevChrom) {
370	        if (_lexicoAssumed) {
371	            // ERROR.
372	            fprintf(stderr, "ERROR: Sort order was unspecified, and file %s is not sorted lexicographically.\n",
373	                    _context->getInputFileName(fileIdx).c_str());
374	            fprintf(stderr, "       Please rerun with the -g option for a genome file.\n       See documentation for details.\n");
375	            exit(1);
376	        }
377	        _lexicoDisproven = true;
378	    }
379	}
380	
381	bool NewChromSweep::queryChromAfterDbRec(const Record *dbRec)
382	{
383	    //If using a genome file, compare chrom ids.
384	    //Otherwise, compare global order, inserting as needed.
385	    if (_context->hasGenomeFile()) {
386	        return (_currQueryRec->getChromId() > dbRec->getChromId()) ;
387	    }
388	    //see if query has both
389	    const string &qChrom = _currQueryRec->getChrName();
390	    const string &dbChrom = dbRec->getChrName();
391	    const _orderTrackType *track = _fileTracks[_currQueryRec->getFileIdx()];
392	    _orderTrackType::const_iterator iter = track->find(qChrom);
393	
